insert into rubrique (cle, libelle, aide, ordre, defaut) values
  ('social', 'Effectifs et mouvements', 'Ce que la paie sait déjà. C''est le dénominateur de presque tout le reste.', 1, true),
  ('securite', 'Sécurité', 'Ce que le registre du site consigne déjà, période par période.', 2, true),
  ('formation', 'Formation', 'Volume et nombre de personnes formées, toutes formations confondues.', 3, true),
  ('diversite', 'Diversité', 'Comptages simples. Aucun index réglementaire n''est calculé ici.', 4, true),
  ('energie', 'Énergie et eau', 'Les relevés de vos factures. C''est la question la plus fréquente des questionnaires clients, et celle qui traîne le plus.', 5, false),
  ('dechets', 'Déchets', 'Les tonnages de vos bordereaux d''enlèvement, site par site.', 6, false),
  ('mobilite', 'Mobilité et flotte', 'Les déplacements domicile-travail et les véhicules du site.', 7, false),
  ('achats', 'Achats', 'Le poids des fournisseurs proches et du secteur protégé dans vos achats.', 8, false)
on conflict (cle) do update set
  libelle = excluded.libelle, aide = excluded.aide,
  ordre = excluded.ordre, defaut = excluded.defaut, active = true;

