-- Ce qui a quitté le catalogue est désactivé, jamais supprimé : les valeurs
-- déjà saisies sous cette clé restent lisibles, et les rapports qui les citent
-- restent vrais.
update indicateur set active = false where cle not in ('effectif_fin', 'entrees', 'sorties', 'heures_travaillees', 'at_avec_arret', 'at_sans_arret', 'at_trajet', 'jours_arret', 'formation_heures', 'formation_benef', 'femmes', 'elec_kwh', 'gaz_kwh', 'carburant_l', 'eau_m3', 'dechets_kg', 'dechets_valorises_kg', 'biodechets_kg', 'flotte', 'flotte_electrique', 'places_recharge', 'forfait_mobilite', 'achats_montant', 'achats_locaux', 'achats_esat', 'fournisseurs', 'boeth', 'tf1', 'tf2', 'tg', 'if_', 'turnover', 'part_femmes', 'part_valorise', 'part_flotte_elec', 'part_achats_locaux', 'elec_par_salarie');
update rubrique  set active = false where cle not in ('social', 'securite', 'formation', 'diversite', 'energie', 'dechets', 'mobilite', 'achats');
